package com.hbm.satellite.control.client;
import com.hbm.satellite.*;import com.hbm.satellite.control.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class SatelliteLinkerJade implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Data.INSTANCE,SatelliteLinkerBlockEntity.class);}@Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Data.INSTANCE,SatelliteLinkerBlock.class);}
 private enum Data implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return ResourceLocation.parse("hbm:satellite_linker_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){if(accessor.getBlockEntity() instanceof SatelliteLinkerBlockEntity linker)for(int i=0;i<3;i++){var stack=linker.getItem(i);if(stack.getItem() instanceof SatelliteFrequency)tag.putInt("hbm:sat_freq_"+i,SatelliteFrequency.getFreqS(stack));}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){var tag=accessor.getServerData();for(int i=0;i<3;i++)if(tag.contains("hbm:sat_freq_"+i))tooltip.add(Component.translatable("jade.hbm.satellite_linker.frequency",i+1,tag.getInt("hbm:sat_freq_"+i)));}}
}
